class Solution:
    def countSubstrings(self, s):
        n, total = len(s), 0
        for c in range(n):
            for l, r in ((c, c), (c, c + 1)):
                while l >= 0 and r < n and s[l] == s[r]:
                    total += 1
                    l -= 1
                    r += 1
        return total

