class Solution:
    def numDecodings(self, s):
        prev2, prev1 = 1, (0 if s[0] == "0" else 1)   # ways for prefixes of length i-2, i-1
        for i in range(2, len(s) + 1):
            cur = 0
            if s[i - 1] != "0":
                cur += prev1
            if s[i - 2] != "0" and int(s[i - 2:i]) <= 26:
                cur += prev2
            prev2, prev1 = prev1, cur
        return prev1

