class Solution:
    def wordBreak(self, s, wordDict):
        words = set(wordDict)
        lens = sorted({len(w) for w in words})
        n = len(s)
        ok = [True] + [False] * n          # ok[i]: s[:i] can be segmented
        for i in range(1, n + 1):
            for L in lens:
                if L > i:
                    break
                if ok[i - L] and s[i - L:i] in words:
                    ok[i] = True
                    break
        return ok[n]

