partition-equal-subset-sum.solution:
class Solution:
    def canPartition(self, nums):
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        reach = [True] + [False] * target
        for x in nums:
            for s in range(target, x - 1, -1):     # downwards: each item used at most once
                if reach[s - x]:
                    reach[s] = True
            if reach[target]:
                return True
        return reach[target]

