    def minPathSum(self, grid):
        n = len(grid[0])
        INF = float("inf")
        row = [INF] * n
        row[0] = 0
        for r in grid:
            row[0] += r[0]
            for j in range(1, n):
                row[j] = min(row[j], row[j - 1]) + r[j]
        return row[-1]

