class Solution:
    def maximalSquare(self, matrix):
        n = len(matrix[0])
        prev = [0] * (n + 1)
        best = 0
        for row in matrix:
            cur = [0] * (n + 1)
            for j in range(1, n + 1):
                if row[j - 1] == "1":
                    cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
                    if cur[j] > best:
                        best = cur[j]
            prev = cur
        return best * best

