class Solution:
    def knapsack(self, weights, values, capacity):
        best = [0] * (capacity + 1)        # best[c]: max value with weight <= c
        for w, v in zip(weights, values):
            for c in range(capacity, w - 1, -1):
                cand = best[c - w] + v
                if cand > best[c]:
                    best[c] = cand
        return best[capacity]

