longest-increasing-path-in-a-matrix.solution:
from collections import deque

class Solution:
    def longestIncreasingPath(self, matrix):
        m, n = len(matrix), len(matrix[0])
        out = [[0] * n for _ in range(m)]         # number of strictly larger neighbours
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
        for i in range(m):
            for j in range(n):
                v = matrix[i][j]
                for di, dj in dirs:
                    a, b = i + di, j + dj
                    if 0 <= a < m and 0 <= b < n and matrix[a][b] > v:
                        out[i][j] += 1
        layer = deque((i, j) for i in range(m) for j in range(n) if out[i][j] == 0)
        depth = 0
        while layer:                               # peel local maxima layer by layer
            depth += 1
            for _ in range(len(layer)):
                i, j = layer.popleft()
                v = matrix[i][j]
                for di, dj in dirs:
                    a, b = i + di, j + dj
                    if 0 <= a < m and 0 <= b < n and matrix[a][b] < v:
                        out[a][b] -= 1
                        if out[a][b] == 0:
                            layer.append((a, b))
        return depth

