class Solution:
    def longestCommonSubsequence(self, text1, text2):
        if len(text2) > len(text1):
            text1, text2 = text2, text1
        prev = [0] * (len(text2) + 1)
        for a in text1:
            cur = [0]
            for k, b in enumerate(text2):
                if a == b:
                    cur.append(prev[k] + 1)
                else:
                    cur.append(cur[k] if cur[k] > prev[k + 1] else prev[k + 1])
            prev = cur
        return prev[-1]

