class Solution:
    def findTargetSumWays(self, nums, target):
        ways = {0: 1}
        for x in nums:
            nxt = {}
            for s, c in ways.items():
                nxt[s + x] = nxt.get(s + x, 0) + c
                nxt[s - x] = nxt.get(s - x, 0) + c
            ways = nxt
        return ways.get(target, 0)

