distinct-subsequences.solution:
class Solution:
    def numDistinct(self, s, t):
        m = len(t)
        if m > len(s):
            return 0
        ways = [1] + [0] * m            # ways[j]: ways to form t[:j] from the prefix of s seen so far
        for ch in s:
            for j in range(m, 0, -1):   # downwards so each s-char is used once per subsequence
                if t[j - 1] == ch:
                    ways[j] += ways[j - 1]
        return ways[m]

